// Fan a topic list and a platform list into one item per pair, and build the
// exact request body for each here rather than in an expression - the target
// array is nested and an exclude list has to be spliced into it.
const cfg = $('Settings').first().json;

const split = (v) => String(v || '')
  .split(',')
  .map((s) => s.trim())
  .filter(Boolean);

const topics = split(cfg.category_topics);
const platforms = split(cfg.platforms).map((p) => p.toLowerCase());
const excludeDomains = split(cfg.exclude_domains);

if (!topics.length) {
  throw new Error('Settings.category_topics is empty. Give it at least one category, e.g. "email marketing software".');
}
if (!platforms.length) {
  throw new Error('Settings.platforms is empty. Use chat_gpt, google, or both.');
}

const ALLOWED = ['chat_gpt', 'google'];
const bad = platforms.filter((p) => !ALLOWED.includes(p));
if (bad.length) {
  throw new Error('platforms must be chat_gpt and/or google. Got: ' + bad.join(', '));
}

const size = Math.min(Math.max(Number(cfg.leaderboard_size) || 25, 5), 100);
const notes = [];

const out = [];
for (const topic of topics) {
  for (const platform of platforms) {
    // chat_gpt data exists for the United States and English only. Ask for
    // Germany and the response is an empty result set, not an error - so the
    // run would report that nobody mentions you anywhere, which is worse than
    // being wrong loudly.
    let location = String(cfg.location || 'United States');
    if (platform === 'chat_gpt' && location !== 'United States') {
      notes.push('chat_gpt is United States only - "' + location + '" was ignored for that platform.');
      location = 'United States';
    }

    const target = [{
      keyword: topic,
      search_filter: 'include',
      search_scope: ['answer'],
      match_type: 'word_match',
    }];
    // Excluding a domain works. Excluding a keyword does not - measured
    // 2026-09-05: excluding "jobs" left total_count identical at 11,642, while
    // excluding indeed.com took it to 10,092. So only domains are offered.
    for (const d of excludeDomains) {
      target.push({
        domain: d.replace(/^https?:\/\//, '').replace(/^www\./, ''),
        search_filter: 'exclude',
        search_scope: ['sources'],
        include_subdomains: true,
      });
    }

    const base = {
      platform,
      target,
      location_name: location,
      language_name: 'English',
      limit: size,
      internal_list_limit: 10,
    };

    out.push({
      json: {
        topic_key: topic.toLowerCase() + '|' + platform,
        topic,
        platform,
        location,
        brand: String(cfg.brand || '').trim(),
        domain: String(cfg.domain || '').trim().replace(/^https?:\/\//, '').replace(/^www\./, ''),
        notes,
        body_brands: [base],
        body_pages: [{ ...base, limit: Math.min(size, 20) }],
      },
    });
  }
}

return out;

// The HTTP node emits one item per input item, in request order, so response i
// belongs to plan i. Nothing in the response repeats the topic, so there is no
// other way to pair them.
const plans = $('Plan The Questions').all().map((i) => i.json);
const responses = $input.all();

// A category label is not a brand. The API returns both in one list: for
// "email marketing software" positions 3, 7, 10, 12 and 22 were "CRM software
// company", "CRM platform", "technology company", "email marketing platform"
// and "marketing automation platform". Ranking a client below "technology
// company" is not a finding, so they are dropped by their trailing noun.
const CATEGORY_TAIL = /\b(company|companies|platform|platforms|software|tool|tools|service|services|agency|agencies|provider|providers|solution|solutions|vendor|vendors|system|systems|app|apps|marketplace|marketplaces|network|networks|brand|brands|business|businesses|website|websites|store|stores|firm|firms|retailer|retailers|manufacturer|manufacturers)$/i;

const out = [];

for (let i = 0; i < responses.length; i++) {
  const plan = plans[i] || {};
  const body = responses[i].json || {};

  // DataForSEO answers a bad location, an unsupported filter and an empty
  // account with HTTP 200 and a status_code in the body. Reading result[0]
  // without checking gives "cannot read properties of undefined" three nodes
  // later, blaming the wrong node.
  if (Number(body.status_code) !== 20000) {
    throw new Error(
      'DataForSEO refused the leaderboard request for "' + plan.topic + '": ' +
      body.status_code + ' ' + String(body.status_message || '').slice(0, 200)
    );
  }
  const task = (body.tasks || [])[0] || {};
  if (Number(task.status_code) !== 20000) {
    throw new Error(
      'DataForSEO refused the leaderboard task for "' + plan.topic + '": ' +
      task.status_code + ' ' + String(task.status_message || '').slice(0, 200)
    );
  }

  const result = (task.result || [])[0] || {};
  const agg = result.aggregated_metrics || {};
  // The honest denominator. The visible rows hold a small fraction of the
  // mentions - 25 rows covered 1,838 of them out of a 1,383-brand list.
  const totalMentions = Number((agg.total || {}).mentions) || 0;

  const brandWanted = String(plan.brand || '').toLowerCase();
  const raw = (result.items || []).map((it) => ({
    name: String(it.brand || '').trim(),
    mentions: Number((it.total || {}).mentions) || 0,
    ai_search_volume: Number((it.total || {}).ai_search_volume) || 0,
  })).filter((b) => b.name);

  const isOwn = (name) => brandWanted && name.toLowerCase() === brandWanted;
  const ranked = raw.filter((b) => isOwn(b.name) || !CATEGORY_TAIL.test(b.name));
  const droppedLabels = raw.length - ranked.length;

  let brandRank = 0;
  let brandMentions = 0;
  for (let r = 0; r < ranked.length; r++) {
    if (isOwn(ranked[r].name)) {
      brandRank = r + 1;
      brandMentions = ranked[r].mentions;
      break;
    }
  }

  const leader = ranked[0] || { name: '', mentions: 0 };
  const sourceDomains = (agg.sources_domain || []).map((s) => ({
    domain: String(s.key || ''),
    mentions: Number(s.mentions) || 0,
  }));
  let domainRank = 0;
  for (let d = 0; d < sourceDomains.length; d++) {
    const bare = sourceDomains[d].domain.replace(/^www\./, '');
    if (plan.domain && bare === plan.domain) { domainRank = d + 1; break; }
  }

  out.push({
    json: {
      ...plan,
      brands_total: Number(result.total_count) || ranked.length,
      total_mentions: totalMentions,
      dropped_labels: droppedLabels,
      brand_rank: brandRank,
      brand_mentions: brandMentions,
      // Share of every mention captured for this topic, not of the rows shown.
      share_pct: totalMentions ? Math.round((brandMentions / totalMentions) * 10000) / 100 : 0,
      leader: leader.name,
      leader_mentions: leader.mentions,
      top_brands: ranked.slice(0, 10),
      cited_domains: sourceDomains.slice(0, 10),
      domain_rank: domainRank,
    },
  });
}

return out;

// This branch runs beside the leaderboard branch rather than behind it - two
// paid calls that need nothing from each other should not be serialised - so it
// pairs against the plan, not against the leaderboard. Reaching into a node on
// a parallel branch is exactly the ordering assumption the Merge below exists
// to remove.
const rows = $('Plan The Questions').all().map((i) => i.json);
const responses = $input.all();

const out = [];

for (let i = 0; i < responses.length; i++) {
  const row = rows[i] || {};
  const body = responses[i].json || {};

  // A failed page lookup should not lose the leaderboard that already
  // succeeded, so this one records the failure and carries the row through.
  let pages = [];
  let pagesError = '';

  const task = (body.tasks || [])[0] || {};
  if (Number(body.status_code) !== 20000 || Number(task.status_code) !== 20000) {
    pagesError = String(task.status_message || body.status_message || 'unknown error').slice(0, 160);
  } else {
    const items = ((task.result || [])[0] || {}).items || [];
    const seen = new Map();
    for (const it of items) {
      // Cited URLs come back tagged: the same page appears once as
      // https://x.com/p and once as https://x.com/p?utm_source=chatgpt.com.
      // Counted naively that is two pages, each with half the mentions.
      const url = String(it.page || '').split('#')[0]
        .replace(/[?&]utm_source=chatgpt\.com/, '')
        .replace(/[?&]$/, '');
      if (!url) continue;
      const mentions = Number((it.total || {}).mentions) || 0;
      const prev = seen.get(url);
      if (prev) { prev.mentions += mentions; } else { seen.set(url, { url, mentions }); }
    }
    pages = [...seen.values()].sort((a, b) => b.mentions - a.mentions).slice(0, 8);
  }

  // The Code node sandbox has no `URL` constructor, so the host comes off the
  // string. Wrapping `new URL` in a try/catch would be worse than useless here:
  // it throws on every row, the catch swallows it, and the count of your own
  // quoted pages is silently zero forever.
  const hostOf = (u) => (String(u).match(/^https?:\/\/([^/?#]+)/i) || ['', ''])[1]
    .toLowerCase().replace(/^www\./, '');
  const yours = row.domain ? pages.filter((p) => hostOf(p.url) === row.domain) : [];

  out.push({
    json: {
      topic_key: row.topic_key,
      quoted_pages: pages,
      your_quoted_pages: yours.length,
      pages_error: pagesError,
    },
  });
}

return out;

// One item out, holding every topic. The email is one email and the model is
// asked once, so splitting here would only buy identical answers at full price.
//
// The input is the Merge barrier, which appends three branches into one stream
// of mixed shapes. Reading them back by name is the point of the barrier - it
// guarantees all three have finished, and it keeps the join explicit.
const pagesByKey = new Map();
for (const item of $('Read The Quoted Pages').all()) {
  const p = item.json || {};
  if (p.topic_key) pagesByKey.set(String(p.topic_key), p);
}

const rows = $('Read The Leaderboard').all().map((i) => {
  const r = i.json || {};
  const p = pagesByKey.get(String(r.topic_key)) || {};
  return { ...r, quoted_pages: p.quoted_pages || [], your_quoted_pages: p.your_quoted_pages || 0, pages_error: p.pages_error || '' };
});

const today = new Date().toISOString().slice(0, 10);

// The history sheet is append-only, so a topic has one row per week it ran and
// the comparison wants the newest row that is not today's. Taking the last row
// with a matching key would compare this run against itself the moment somebody
// runs it twice in a morning.
const prior = new Map();
for (const item of $('Read What You Saw Last Week').all()) {
  const r = item.json || {};
  const key = r && r.topic_key ? String(r.topic_key) : '';
  if (!key) continue;
  const on = String(r.checked_on || '');
  if (!on || on >= today) continue;
  const held = prior.get(key);
  if (!held || on > String(held.checked_on || '')) prior.set(key, r);
}
const out = [];
const movers = [];
const notes = new Set();

for (const row of rows) {
  for (const n of (row.notes || [])) notes.add(n);
  if (row.pages_error) notes.add('Quoted pages unavailable for "' + row.topic + '": ' + row.pages_error);

  const was = prior.get(row.topic_key);
  // A rank of 0 means "not in the leaderboard at all", which is a real state
  // and not a zero. Treating it as a number would make an entry from nowhere
  // look like a fall from first place.
  const hadRank = was && Number(was.brand_rank) > 0 ? Number(was.brand_rank) : 0;
  const nowRank = Number(row.brand_rank) || 0;

  let movement = 'first look';
  let rankDelta = 0;
  if (was) {
    if (hadRank && nowRank) {
      rankDelta = hadRank - nowRank;
      movement = rankDelta > 0 ? 'up ' + rankDelta : rankDelta < 0 ? 'down ' + Math.abs(rankDelta) : 'unchanged';
    } else if (!hadRank && nowRank) {
      movement = 'entered the list';
    } else if (hadRank && !nowRank) {
      movement = 'dropped out of the list';
    } else {
      movement = 'still unranked';
    }
  }

  const shareDelta = was ? Math.round(((Number(row.share_pct) || 0) - (Number(was.share_pct) || 0)) * 100) / 100 : 0;
  if (movement !== 'unchanged' && movement !== 'still unranked') movers.push(row.topic + ' (' + row.platform + '): ' + movement);

  out.push({ ...row, was_rank: hadRank, rank_delta: rankDelta, movement, share_delta: shareDelta, checked_on: today });
}

// A topic nobody asks an assistant about returns a legitimately empty set. That
// is a configuration answer, not a report, so it takes the quiet branch.
const withData = out.filter((r) => Number(r.total_mentions) > 0).length;

return [{
  json: {
    checked_on: today,
    topics_with_data: withData,
    topic_count: out.length,
    movers,
    notes: [...notes],
    rows: out,
    // A second, narrower copy for the sheet. The Split Out below hands whatever
    // it finds straight to an append that maps input fields to columns, so a
    // row carrying quoted_pages and notes would put a JSON blob in a cell.
    sheet_rows: out.map((r) => ({
      checked_on: r.checked_on,
      topic_key: r.topic_key,
      topic: r.topic,
      platform: r.platform,
      brand_rank: r.brand_rank,
      brand_mentions: r.brand_mentions,
      share_pct: r.share_pct,
      leader: r.leader,
      leader_mentions: r.leader_mentions,
    })),
  },
}];

// single-item input: one digest per run, and the model was asked once.
const payload = $('Compare With Last Week').first().json || {};
const rows = payload.rows || [];
const commentary = String(($input.first().json || {}).text || '').trim();

const esc = (s) => String(s == null ? '' : s)
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

const arrow = (r) => {
  if (r.movement === 'first look') return 'first look';
  if (r.rank_delta > 0) return '&#9650; ' + r.rank_delta;
  if (r.rank_delta < 0) return '&#9660; ' + Math.abs(r.rank_delta);
  return esc(r.movement);
};

const rank = (r) => (Number(r.brand_rank) > 0 ? '#' + r.brand_rank : 'unranked');

const body = rows.map((r) => {
  const pages = (r.quoted_pages || []).slice(0, 3)
    .map((p) => '<div style="font-size:12px;color:#555">' + esc(p.url).slice(0, 110) + ' &middot; ' + p.mentions + '</div>')
    .join('');
  return '<tr>' +
    '<td style="padding:8px;border-bottom:1px solid #eee"><strong>' + esc(r.topic) + '</strong>' +
    '<div style="font-size:12px;color:#777">' + esc(r.platform) + '</div>' + pages + '</td>' +
    '<td style="padding:8px;border-bottom:1px solid #eee;text-align:center">' + rank(r) + '</td>' +
    '<td style="padding:8px;border-bottom:1px solid #eee;text-align:center">' + arrow(r) + '</td>' +
    '<td style="padding:8px;border-bottom:1px solid #eee;text-align:center">' + (Number(r.share_pct) || 0) + '%</td>' +
    '<td style="padding:8px;border-bottom:1px solid #eee">' + esc(r.leader) + ' <span style="color:#777">(' + (Number(r.leader_mentions) || 0) + ')</span></td>' +
    '</tr>';
}).join('');

const notes = (payload.notes || []).length
  ? '<p style="font-size:12px;color:#a00">' + payload.notes.map(esc).join('<br>') + '</p>'
  : '';

const html = '<div style="font-family:-apple-system,Segoe UI,Arial,sans-serif;max-width:760px">' +
  '<h2 style="margin:0 0 4px">AI visibility &middot; ' + esc(payload.checked_on) + '</h2>' +
  '<p style="color:#555;margin:0 0 16px">' + rows.length + (rows.length === 1 ? ' topic checked.' : ' topic/platform pairs checked.') + '</p>' +
  (commentary ? '<div style="white-space:pre-wrap;background:#f6f8fa;padding:12px;border-radius:6px;margin-bottom:16px">' + esc(commentary) + '</div>' : '') +
  '<table style="border-collapse:collapse;width:100%;font-size:14px">' +
  '<tr style="text-align:left;background:#f0f2f5">' +
  '<th style="padding:8px">Topic</th><th style="padding:8px">Rank</th><th style="padding:8px">Week</th>' +
  '<th style="padding:8px">Share</th><th style="padding:8px">Leads</th></tr>' +
  body + '</table>' + notes + '</div>';

return [{ json: { html, subject: 'AI visibility - ' + payload.checked_on } }];
